using AOT;
using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;

[BurstCompile]
public static class Rules
{
    public delegate float SpeedRule(float distance, float baseSpeed);

    [BurstCompile]
    [MonoPInvokeCallback(typeof(SpeedRule))]   // needed for IL2CPP
    public static float Flee(float distance, float baseSpeed) => baseSpeed * 2f;
}

[BurstCompile]
struct MoveJob : IJobParallelFor
{
    public FunctionPointer<Rules.SpeedRule> rule;   // picked at runtime
    [ReadOnly] public NativeArray<float> distance;
    public NativeArray<float> speed;
    public float baseSpeed;

    public void Execute(int i)
    {
        speed[i] = rule.Invoke(distance[i], baseSpeed);
    }
}

public static class RuleSetup
{
    public static FunctionPointer<Rules.SpeedRule> Compile()
    {
        // once, from managed code; the caller caches the result
        return BurstCompiler.CompileFunctionPointer<Rules.SpeedRule>(Rules.Flee);
    }
}

