public abstract class Stats
{
    // one slot of native memory, visible to C# and to Burst code
    public static readonly SharedStatic<int> Hits =
        SharedStatic<int>.GetOrCreate<Stats, HitsKey>();
    class HitsKey { }                  // a key type that names this field

    static Stats() { Hits.Data = 0; }  // initialise in C# before Burst reads it
}

[BurstCompile]
struct CountJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float> distance;
    public void Execute(int i)
    {
        if (distance[i] < 1f)
            Interlocked.Increment(ref Stats.Hits.Data);   // Data is a ref
    }
}

[BurstCompile]
struct DamageJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float> damage;
    public void Execute(int i)
    {
        if (damage[i] > 0f)
            Stats.Hits.Data++;
    }
}
